export const validateCtaDestination = validateSiteDestination;

export function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]!);
}

function siteMarkup(page: GeneratedPage, siteSettings: SiteSettings, preview = false, heroImage: HeroImageAsset | null = null, template: SiteTemplate = DEFAULT_SITE_TEMPLATE): string {
  const styleClass = page.style.toLowerCase();
  const classes = ["site-mock", ...(template.id === "restaurant" ? ["restaurant-site"] : []), ...(template.id === "fashion" ? ["fashion-site"] : []), ...(template.id === "real-estate" ? ["real-estate-site"] : []), styleClass, page.layout, ...(preview ? ["preview"] : [])].join(" ");
  const appearanceStyle = effectiveAppearanceCss(page.style, siteSettings.appearance);
  const availableSectionAnchors = template.id === "restaurant" ? new Set([
    "#top", "#site-headline", "#site-menu",
    ...(template.content.story?.trim() ? ["#site-story"] : []),
    ...(template.content.location?.trim() || template.content.openingHours?.trim() ? ["#site-visit"] : []),
  ]) : template.id === "fashion" ? new Set([
    "#top", "#site-headline", "#site-collections",
    ...(template.content.brandStory?.trim() ? ["#site-brand-story"] : []),
  ]) : template.id === "real-estate" ? new Set([
    "#top", "#site-headline", "#site-properties",
    ...(template.content.agencyStory?.trim() ? ["#site-agency-story"] : []),
  ]) : new Set(["#top", "#site-headline"]);
  const ctaDestinationResult = SiteSettingsSchema.shape.ctaDestination.safeParse(siteSettings.ctaDestination);
  const candidateCtaHref = ctaDestinationResult.success ? validateSiteDestination(ctaDestinationResult.data) : undefined;
  const ctaHref = candidateCtaHref?.startsWith("#") && !availableSectionAnchors.has(candidateCtaHref) ? undefined : candidateCtaHref;
  const cta = ctaHref
    ? `<a class="site-cta" href="${escapeHtml(ctaHref)}">${escapeHtml(page.callToAction)} <span aria-hidden="true">↗</span></a>`
    : `<span class="site-cta site-cta-text">${escapeHtml(page.callToAction)}</span>`;
  const features = page.features.map((feature) => `<li>${escapeHtml(feature)}</li>`).join("");
  const navigation = siteSettings.navigation.map(({ label, destination }) => {
    const destinationResult = SiteDestinationSchema.safeParse(destination);
    const href = destinationResult.success ? validateSiteDestination(destinationResult.data) : undefined;
    if (href?.startsWith("#") && !availableSectionAnchors.has(href)) {
      return `<span>${escapeHtml(label)}</span>`;
    }
    return href ? `<a href="${escapeHtml(href)}">${escapeHtml(label)}</a>` : `<span>${escapeHtml(label)}</span>`;
  }).join("");
  const hasPropertiesNavigation = siteSettings.navigation.some(({ destination }) => destination === "#site-properties");
  const renderedNavigation = template.id === "real-estate" && !hasPropertiesNavigation
    ? `${navigation}<a href="#site-properties">Properties</a>`
    : navigation;
  const restaurantFallback = `<div class="restaurant-artboard"><div class="restaurant-steam"></div><div class="restaurant-plate"><div class="restaurant-rice"></div><div class="restaurant-chicken"></div><i class="restaurant-chicken-bone"></i><div class="restaurant-plantain"><i class="restaurant-plantain-slice restaurant-plantain-slice-one"></i><i class="restaurant-plantain-slice restaurant-plantain-slice-two"></i><i class="restaurant-plantain-slice restaurant-plantain-slice-three"></i></div><i class="restaurant-leaf restaurant-leaf-one"></i><i class="restaurant-leaf restaurant-leaf-two"></i><i class="restaurant-leaf restaurant-leaf-three"></i></div><div class="restaurant-grill"></div></div>`;
  const art = heroImage
    ? `<div class="site-art" aria-hidden="true"><img class="site-hero-image" src="${escapeHtml(heroImageDataUrl(heroImage))}" alt="" /></div>`
    : template.id === "restaurant"
      ? `<div class="site-art restaurant-art" aria-hidden="true">${restaurantFallback}</div>`
      : template.id === "fashion"
        ? `<div class="site-art fashion-art" aria-hidden="true"><div class="fashion-artboard"><span class="fashion-art-index">STUDIO / 01</span><div class="fashion-art-fold fashion-art-fold-back"></div><div class="fashion-art-fold fashion-art-fold-front"></div><div class="fashion-garment"><i></i></div><span class="fashion-art-caption">FORM · FABRIC · FUNCTION</span></div></div>`
        : template.id === "real-estate"
          ? `<div class="site-art real-estate-art" aria-hidden="true"><div class="real-estate-artboard"><span class="real-estate-art-label">A place to call home</span><div class="real-estate-skyline"><i class="real-estate-building real-estate-building-one"></i><i class="real-estate-building real-estate-building-two"></i><i class="real-estate-building real-estate-building-three"></i></div><div class="real-estate-landscape"></div></div></div>`
        : `<div class="site-art" aria-hidden="true"><div class="site-arch"><div class="site-orb"></div><div class="site-vase site-vase-one"></div><div class="site-vase site-vase-two"></div><div class="site-table"></div><span class="site-spark">✳</span></div><span class="site-art-caption">Fig. 01 — The everyday edit</span></div>`;

  if (template.id === "restaurant") return restaurantMarkup(classes, appearanceStyle, page, template.content, navigation, cta, art);
  if (template.id === "fashion") return fashionMarkup(classes, appearanceStyle, page, template.content, navigation, cta, art);
  if (template.id === "real-estate") return realEstateMarkup(classes, appearanceStyle, page, template.content, renderedNavigation, cta, art);

  return `<div class="${classes}" style="${escapeHtml(appearanceStyle)}"><header id="top" class="site-nav"><span class="site-logo">${escapeHtml(page.businessName)}</span><nav class="site-nav-links" aria-label="Website sections">${navigation}</nav></header><main><section class="site-hero" aria-labelledby="site-headline"><div class="site-copy"><span class="site-kicker">MADE WITH INTENTION <i aria-hidden="true">✦</i></span><h1 id="site-headline">${escapeHtml(page.headline)}</h1><p>${escapeHtml(page.subheadline)}</p><div class="site-actions">${cta}<span class="site-audience">For ${escapeHtml(page.audience)}</span></div><ul class="site-features">${features}</ul></div>${art}</section></main><footer class="site-bottom"><span>Designed for the everyday</span><span>01 / 03</span></footer></div>`;
}

function fashionMarkup(classes: string, appearanceStyle: string, page: GeneratedPage, content: FashionContent, navigation: string, cta: string, art: string) {
  const collections = content.collectionHighlights.map(({ name, description }, index) => `<li class="fashion-collection"><span class="fashion-collection-index">0${index + 1}</span><article><h3>${escapeHtml(name)}</h3><p>${escapeHtml(description)}</p></article></li>`).join("");
  const brandStory = content.brandStory?.trim()
    ? `<section class="fashion-story" id="site-brand-story" aria-labelledby="fashion-story-heading"><span class="site-kicker">BRAND STORY</span><h2 id="fashion-story-heading">Brand story</h2><p>${escapeHtml(content.brandStory)}</p></section>`
    : "";
  return `<div class="${classes}" style="${escapeHtml(appearanceStyle)}"><header id="top" class="site-nav fashion-nav"><span class="site-logo">${escapeHtml(page.businessName)}</span><nav class="site-nav-links" aria-label="Fashion brand navigation">${navigation}</nav></header><main><section class="site-hero fashion-hero" aria-labelledby="site-headline"><div class="site-copy"><span class="site-kicker">THE NEW EDIT <i aria-hidden="true">✦</i></span><h1 id="site-headline">${escapeHtml(page.headline)}</h1><p>${escapeHtml(page.subheadline)}</p><div class="site-actions">${cta}<span class="site-audience">For ${escapeHtml(page.audience)}</span></div></div>${art}</section><section class="fashion-collections" id="site-collections" aria-labelledby="fashion-collections-heading"><div class="fashion-section-heading"><div><span class="site-kicker">COLLECTIONS / 01—0${content.collectionHighlights.length}</span><h2 id="fashion-collections-heading">Collection highlights</h2></div><p>Explore the collection directions shaping the studio.</p></div><ol class="fashion-collection-list">${collections}</ol></section>${brandStory}</main><footer class="site-bottom fashion-footer"><span>${escapeHtml(page.businessName)}</span><a href="#top">Back to top</a></footer></div>`;
}

function restaurantMarkup(classes: string, appearanceStyle: string, page: GeneratedPage, content: RestaurantContent, navigation: string, cta: string, art: string) {
  const menu = content.menuHighlights.map(({ name, description }) => `<li class="restaurant-dish"><article><h3>${escapeHtml(name)}</h3><p>${escapeHtml(description)}</p></article></li>`).join("");
  const story = content.story?.trim()
    ? `<section class="restaurant-story" id="site-story" aria-labelledby="site-story-heading"><span class="site-kicker">OUR STORY</span><h2 id="site-story-heading">Our story</h2><p class="restaurant-story-copy">${escapeHtml(content.story)}</p></section>`
    : "";
  const visitDetails = [
    ...(content.location?.trim() ? [`<div><dt>Location</dt><dd>${escapeHtml(content.location)}</dd></div>`] : []),
    ...(content.openingHours?.trim() ? [`<div><dt>Opening hours</dt><dd>${escapeHtml(content.openingHours)}</dd></div>`] : []),
  ].join("");
  const visit = visitDetails
    ? `<section class="restaurant-visit" id="site-visit" aria-labelledby="site-visit-heading"><span class="site-kicker">VISIT</span><h2 id="site-visit-heading">Restaurant information</h2><dl class="restaurant-visit-grid">${visitDetails}</dl></section>`
    : "";
  return `<div class="${classes}" style="${escapeHtml(appearanceStyle)}"><header id="top" class="site-nav restaurant-nav"><span class="site-logo">${escapeHtml(page.businessName)}</span><nav class="site-nav-links" aria-label="Restaurant navigation">${navigation}</nav></header><main><section class="site-hero restaurant-hero" aria-labelledby="site-headline"><div class="site-copy"><span class="site-kicker">RESTAURANT <i aria-hidden="true">✦</i></span><h1 id="site-headline">${escapeHtml(page.headline)}</h1><p>${escapeHtml(page.subheadline)}</p><div class="site-actions">${cta}<span class="site-audience">For ${escapeHtml(page.audience)}</span></div></div>${art}</section><section class="restaurant-menu" id="site-menu" aria-labelledby="site-menu-heading"><div class="restaurant-section-heading"><span class="site-kicker">MENU</span><h2 id="site-menu-heading">Menu highlights</h2></div><ul class="restaurant-menu-grid">${menu}</ul></section>${story}${visit}</main><footer class="site-bottom restaurant-footer"><span>${escapeHtml(page.businessName)}</span><a href="#top">Back to top</a></footer></div>`;
}

function realEstateMarkup(classes: string, appearanceStyle: string, page: GeneratedPage, content: RealEstateContent, navigation: string, cta: string, art: string) {
  const properties = content.featuredProperties.map(({ name, description }, index) => `<li class="real-estate-property"><span class="real-estate-property-index">PROPERTY HIGHLIGHT / 0${index + 1}</span><article><h3>${escapeHtml(name)}</h3><p>${escapeHtml(description)}</p></article></li>`).join("");
  const story = content.agencyStory?.trim()
    ? `<section class="real-estate-story" id="site-agency-story" aria-labelledby="real-estate-story-heading"><h2 id="real-estate-story-heading">Agency story</h2><p>${escapeHtml(content.agencyStory)}</p></section>`
    : "";
  return `<div class="${classes}" style="${escapeHtml(appearanceStyle)}"><header id="top" class="site-nav real-estate-nav"><span class="site-logo">${escapeHtml(page.businessName)}</span><nav class="site-nav-links" aria-label="Real estate agency navigation">${navigation}</nav></header><main><section class="site-hero real-estate-hero" aria-labelledby="site-headline"><div class="site-copy real-estate-copy"><span class="site-kicker">REAL ESTATE <i aria-hidden="true">✦</i></span><h1 id="site-headline">${escapeHtml(page.headline)}</h1><p>${escapeHtml(page.subheadline)}</p><div class="site-actions">${cta}<span class="site-audience">For ${escapeHtml(page.audience)}</span></div></div>${art}</section><section class="real-estate-properties" id="site-properties" aria-labelledby="real-estate-properties-heading"><div class="real-estate-section-heading"><div><span class="site-kicker">PROPERTY IDEAS / 01—0${content.featuredProperties.length}</span><h2 id="real-estate-properties-heading">Property highlights</h2></div></div><ul class="real-estate-property-list">${properties}</ul></section>${story}</main><footer class="site-bottom real-estate-footer"><span>${escapeHtml(page.businessName)}</span><a href="#top">Back to top</a></footer></div>`;
}

export function renderGeneratedWebsite(page: GeneratedPage, siteSettings: SiteSettings = DEFAULT_SITE_SETTINGS, heroImage: HeroImageAsset | null = null, template: SiteTemplate = DEFAULT_SITE_TEMPLATE): string {
  // Editor fields may be temporarily below their final submission limits while
  // the user is typing. Restrict class-generating values, while escaping all copy.
  const style = VisualStyleSchema.parse(page.style);
  const layout = z.enum(["editorial", "split"]).parse(page.layout);
  // Invalid in-progress editor values stay visible but non-interactive; saves and
  // exports still require the complete strict settings schema.
  const validatedImage = heroImage === null ? null : HeroImageAssetSchema.parse(heroImage);
  const validatedTemplate = SiteTemplateSchema.safeParse(template);
  return siteMarkup({ ...page, style, layout }, siteSettings, true, validatedImage, validatedTemplate.success ? validatedTemplate.data : DEFAULT_SITE_TEMPLATE);
}

export function sanitizeExportFilename(businessName: string): string {
  const slug = businessName.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
    .replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60).replace(/-+$/g, "");
  return `weblander-${slug || "website"}.html`;
}

export function createWebsiteExport(page: unknown, layout: unknown, settingsOrDestination: SiteSettings | string = DEFAULT_SITE_SETTINGS, heroImage: unknown = null, template: unknown = DEFAULT_SITE_TEMPLATE): { html: string; filename: string } {
  const validatedPage = GeneratedPageSchema.parse({ ...(page as object), layout });
  const settings = SiteSettingsSchema.parse(typeof settingsOrDestination === "string"
    ? { ...DEFAULT_SITE_SETTINGS, ctaDestination: settingsOrDestination }
    : settingsOrDestination);
  const contrast = validateAppearanceContrast(validatedPage.style, settings.appearance);
  if (!contrast.valid) throw new Error("The selected appearance does not meet the website contrast requirements.");
  const validatedImage = heroImage === null ? null : HeroImageAssetSchema.parse(heroImage);
  const validatedTemplate = SiteTemplateSchema.parse(template);
  const title = escapeHtml(validatedPage.businessName);
  const description = escapeHtml(validatedPage.subheadline);
  const markup = siteMarkup(validatedPage, settings, false, validatedImage, validatedTemplate);
  const imagePolicy = validatedImage ? " img-src data:" : "";
  const html = `<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<meta name="description" content="${description}">\n<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline';${imagePolicy} base-uri 'none'; form-action 'none'">\n<title>${title}</title>\n<style>${GENERATED_SITE_CSS}</style>\n</head>\n<body>\n${markup}\n</body>\n</html>`;
  return { html, filename: sanitizeExportFilename(validatedPage.businessName) };
}
